const screens=[...document.querySelectorAll('.screen')],navButtons=[...document.querySelectorAll('[data-screen]')];let need='Study room',start='Now',room='Room 3',end='8:30 PM';function show(id){screens.forEach(s=>s.classList.toggle('active',s.id===id));document.querySelectorAll('.bottom button').forEach(b=>b.classList.toggle('active',b.dataset.screen===id));window.scrollTo({top:0,behavior:'smooth'})}navButtons.forEach(b=>b.addEventListener('click',()=>show(b.dataset.screen)));document.querySelectorAll('[data-back]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.back)));document.querySelectorAll('.need').forEach(b=>b.addEventListener('click',()=>{need=b.dataset.need;document.querySelector('#need-copy').textContent=need;show('when')}));document.querySelectorAll('[data-time]').forEach(b=>b.addEventListener('click',()=>{start=b.dataset.time;document.querySelector('#match-copy').textContent=`${need} · ${start}`;show('matches')}));document.querySelectorAll('.match').forEach(b=>b.addEventListener('click',()=>{room=b.dataset.room;document.querySelector('#finish-room').textContent=room;document.querySelector('#finish-start').textContent=start;show('finish')}));document.querySelectorAll('[data-end]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-end]').forEach(x=>x.classList.remove('active'));b.classList.add('active');end=b.dataset.end;document.querySelector('#details').classList.remove('hidden')}));document.querySelector('#confirm').addEventListener('click',()=>{document.querySelector('#success-room').textContent=room;document.querySelector('#success-range').textContent=`${start}–${end}`;show('success')});